// Step 1 prep: clean, filter by date window, sample (keeps LLM cost low)
const WEEKS = 12;
const cutoff = Date.now() - WEEKS * 7 * 864e5;
const feeRe = /brokerage|brokarage|brokrage|charge|\bfees?\b|deduct|\bdp\b|gst|expense ratio|exit load|stamp/i;

// Profanity filter (English + Hinglish): abusive words are masked before the LLM ever sees them
const BAD_SRC = '(^|[^a-z])(fuck[a-z]*|f[*]ck[a-z]*|shit[a-z]*|bullshit|bitch[a-z]*|bastard[a-z]*|asshole[a-z]*|dick[a-z]*|cunt[a-z]*|whore[a-z]*|slut[a-z]*|crap[a-z]*|damn[a-z]*|wtf|stfu|motherf[a-z]*|piss[a-z]*|chutiy[a-z]*|chutiye|bhosd[a-z]*|bsdk|madarchod[a-z]*|maderchod[a-z]*|behenchod[a-z]*|bhenchod[a-z]*|benchod[a-z]*|gandu[a-z]*|gaand[a-z]*|harami[a-z]*|haramkhor[a-z]*|kamina[a-z]*|kamine[a-z]*|lavde[a-z]*|lawde[a-z]*|lodu[a-z]*|randi[a-z]*|saala|saale|kutte|kutta)(?=$|[^a-z])';
const clean = s => String(s).replace(new RegExp(BAD_SRC, 'gi'), (m, p) => p + '***');

let rows = $input.all().map(i => i.json)
  .filter(r => r.Review && String(r.Review).trim().length > 15)
  .map(r => ({
    date: r.Date, rating: Number(r.Rating),
    review: clean(String(r.Review).replace(/\s+/g, ' ')).slice(0, 300),
    votes: Number(r['Helpful votes']) || 0
  }));

const inWindow = rows.filter(r => new Date(r.date).getTime() >= cutoff);
rows = inWindow.length ? inWindow : rows;   // fall back if CSV is older than window

const dates = rows.map(r => new Date(r.date)).filter(d => !isNaN(d));
const minD = new Date(Math.min(...dates)).toISOString().slice(0,10);
const maxD = new Date(Math.max(...dates)).toISOString().slice(0,10);

const fee  = rows.filter(r => feeRe.test(r.review));
const low  = rows.filter(r => r.rating <= 3 && !feeRe.test(r.review)).slice(0, 80);
const high = rows.filter(r => r.rating >= 4 && !feeRe.test(r.review)).slice(0, 40);
const sample = [...fee, ...low, ...high].slice(0, 160);

const reviewsText = sample.map((r, i) => `${i+1}. [${r.rating}★] ${r.review}`).join('\n');
return [{ json: {
  total_reviews: rows.length,
  fee_mentions: fee.length,
  date_range: `${minD} to ${maxD}`,
  run_date: new Date().toISOString().slice(0,10),
  reviews_text: reviewsText
}}];

// EDIT THESE: 2 official sources for the fee explainer. VERIFY they are live & current before running.
return [{ json: {
  url1: 'https://groww.in/pricing',                 // Groww official pricing/charges page
  url2: 'https://REPLACE-WITH-OFFICIAL-SECOND-SOURCE' // e.g. depository (CDSL/NSDL) or SEBI/exchange page on the charge
}}];

// Strip HTML and keep only fee-relevant text (smaller prompt = faster, cheaper Step 3)
const clean = h => String(h || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<(nav|header|footer)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\s+/g, ' ').trim();
// Keep a window starting at the first fee keyword, capped at MAX chars
// Prefer the start of the pricing table; fall back to the first fee keyword after the page title
const anchorRe = /account opening|equity brokerage|schedule of charges|tariff/i;
const feeRe = /\bcharges?\b|\bfees?\b|brokerage/i;
const MAX = 6000;
const focus = t => {
  let i = t.search(anchorRe);
  if (i < 0) { const j = t.slice(200).search(feeRe); i = j < 0 ? 0 : j + 200; }
  let out = t.slice(i, i + MAX);
  // Drop footer / site-map links after the table
  const end = out.search(/Contact Us|All rights reserved|© ?\d{4}/i);
  if (end > 500) out = out.slice(0, end);
  return out;
};
let p1 = '', p2 = '';
try { p1 = focus(clean($('Fetch Official Page 1').first().json.data)); } catch(e) {}
try { p2 = focus(clean($('Fetch Official Page 2').first().json.data)); } catch(e) {}
const cfg = $('Config: Official Sources').first().json;
return [{ json: {
  url1: cfg.url1, url2: cfg.url2,
  source_text: `SOURCE 1 (${cfg.url1}):\n${p1 || '[could not fetch]'}\n\nSOURCE 2 (${cfg.url2}):\n${p2 || '[could not fetch]'}`
}}];

