// Validate constraints + build a compact HTML email for MCP
const ins   = $('Step 1: Review Insights').first().json.output;
const pulse = String($('Step 2: Weekly Pulse').first().json.text || '').trim();
const fee   = String($('Step 3: Fee Explainer').first().json.text || '').trim();
const src   = $('Strip & Merge Sources').first().json;
const cfg   = { url1: src.url1, url2: src.url2 };
const prep  = $('Prep: Clean & Sample').first().json;

const words   = pulse.split(/\s+/).filter(Boolean).length;
const bullets = fee.split('\n').filter(l => /^\s*[-•*]\s+/.test(l)).map(l => l.replace(/^\s*[-•*]\s+/, '').trim());
const today   = new Date(Date.now() + 330 * 60000).toISOString().slice(0,10); // IST date
const hasUrl2 = !!cfg.url2 && !/REPLACE/i.test(cfg.url2);
const checks = {
  pulse_words: words, pulse_ok: words <= 250,
  fee_bullets: bullets.length, fee_ok: bullets.length <= 6,
  themes_ok: (ins.themes||[]).length <= 5,
  quotes_ok: (ins.quotes||[]).length === 3,
  last_checked_ok: /Last checked:/i.test(fee)
};
const all_ok = Object.values(checks).every(v => v === true || typeof v === 'number');

// ---- helpers ----
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
const strip = l => String(l).replace(/^(\d+[.)]|[-•*>])\s*/, '').replace(/^["“]+|["”]+$/g, '').trim();
const section = (md, name) => {
  const hit = md.split(/^##\s+/m).find(p => p.toLowerCase().startsWith(name.toLowerCase()));
  return hit ? hit.split('\n').slice(1).map(l => l.trim()).filter(Boolean) : [];
};
const short = (s, n) => (s.length > n ? s.slice(0, n - 1).trim() + '…' : s);
// Profanity safety net (same list as Prep)
function badRe(f) { return new RegExp('(^|[^a-z])(fuck[a-z]*|f[*]ck[a-z]*|shit[a-z]*|bullshit|bitch[a-z]*|bastard[a-z]*|asshole[a-z]*|dick[a-z]*|cunt[a-z]*|whore[a-z]*|slut[a-z]*|crap[a-z]*|damn[a-z]*|wtf|stfu|motherf[a-z]*|piss[a-z]*|chutiy[a-z]*|chutiye|bhosd[a-z]*|bsdk|madarchod[a-z]*|maderchod[a-z]*|behenchod[a-z]*|bhenchod[a-z]*|benchod[a-z]*|gandu[a-z]*|gaand[a-z]*|harami[a-z]*|haramkhor[a-z]*|kamina[a-z]*|kamine[a-z]*|lavde[a-z]*|lawde[a-z]*|lodu[a-z]*|randi[a-z]*|saala|saale|kutte|kutta)(?=$|[^a-z])', f); }
function clean(s) { return String(s == null ? '' : s).replace(badRe('gi'), (m, p) => p + '***'); }
function isClean(s) { return !badRe('i').test(String(s)) && String(s).indexOf('***') === -1; }

const GREEN = '#00b386';
const h  = t => '<h3 style="margin:22px 0 8px;font-size:15px;color:' + GREEN + '">' + t + '</h3>';
const li = arr => arr.map(x => '<li style="margin:0 0 6px">' + inline(x) + '</li>').join('');

// ---- content (kept short on purpose) ----
const themes      = ((ins.top3 && ins.top3.length) ? ins.top3 : section(pulse, 'Top themes').map(strip)).slice(0, 3).map(clean);
const quotes      = (ins.quotes || []).map(strip).filter(isClean).slice(0, 2).map(q => short(q, 160));
const observation = clean(section(pulse, 'Key observation').join(' '));
const actions     = section(pulse, 'Action ideas').map(strip).slice(0, 3).map(clean);
const feeBullets  = bullets.slice(0, 4).map(clean);

const html =
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;color:#222;font-size:14px;line-height:1.55">' +
    '<div style="background:' + GREEN + ';color:#fff;padding:16px 20px;border-radius:8px 8px 0 0">' +
      '<div style="font-size:18px;font-weight:bold">Groww Weekly Pulse</div>' +
      '<div style="font-size:12px;opacity:.9">' + esc(prep.date_range) + ' &middot; ' + esc(prep.total_reviews) + ' reviews</div>' +
    '</div>' +
    '<div style="padding:4px 20px 20px;border:1px solid #e5e5e5;border-top:0;border-radius:0 0 8px 8px">' +
      h('Top themes') + '<ol style="padding-left:20px;margin:0">' + li(themes) + '</ol>' +
      (observation ? h('Key observation') + '<p style="margin:0">' + inline(observation) + '</p>' : '') +
      (quotes.length ? h('What users say') + quotes.map(q => '<p style="margin:0 0 8px;padding:6px 12px;border-left:3px solid ' + GREEN + ';background:#f6fbf9;font-style:italic;color:#444">' + inline(q) + '</p>').join('') : '') +
      (actions.length ? h('Action ideas') + '<ol style="padding-left:20px;margin:0">' + li(actions) + '</ol>' : '') +
      h('Fee clarification: ' + esc(ins.fee_issue.fee)) + '<ul style="padding-left:20px;margin:0">' + li(feeBullets) + '</ul>' +
      '<p style="margin:18px 0 0;font-size:12px;color:#888">Sources: <a href="' + esc(cfg.url1) + '" style="color:' + GREEN + '">Groww pricing</a>' + (hasUrl2 ? ' &middot; <a href="' + esc(cfg.url2) + '" style="color:' + GREEN + '">link 2</a>' : '') + ' &middot; Last checked ' + today + '</p>' +
    '</div>' +
  '</div>';

const subject = 'Groww Weekly Pulse — ' + today;
const email_body = html;

// ---- structured, readable Google Doc entry (plain text) ----
const plain = s => String(s).replace(/\*\*(.+?)\*\*/g, '$1');
const num = arr => arr.map((x, i) => '   ' + (i + 1) + '. ' + plain(x)).join('\n');
const dot = arr => arr.map(x => '   • ' + plain(x)).join('\n');
const docParts = [
  'GROWW WEEKLY PULSE  |  ' + today,
  'Review window: ' + prep.date_range + '   |   Reviews analysed: ' + prep.total_reviews,
  '',
  'TOP THEMES',
  num(themes)
];
if (observation) docParts.push('', 'KEY OBSERVATION', '   ' + plain(observation));
if (quotes.length) docParts.push('', 'WHAT USERS SAY', quotes.map(q => '   “' + q + '”').join('\n'));
if (actions.length) docParts.push('', 'ACTION IDEAS', num(actions));
docParts.push(
  '',
  'FEE CLARIFICATION: ' + clean(ins.fee_issue.fee),
  '   User confusion: ' + clean(ins.fee_issue.confusion),
  dot(bullets.map(clean)),
  '',
  'SOURCES',
  '   • ' + cfg.url1,
  ...(hasUrl2 ? ['   • ' + cfg.url2] : []),
  '   Last checked: ' + today
);
const log_entry = docParts.join('\n');
return [{ json: { checks, all_ok, subject, email_body, log_entry, pulse: clean(pulse), fee: clean(fee),
  checks_text: JSON.stringify(checks), date_range: prep.date_range }}];
